# Redefine bands
bands = [list(range(0,7)), list(range(7,14)), list(range(14,21)), list(range(21,29))]

blocks = []
current_val = None
for i, band in enumerate(bands):
    vals_in_band = set()
    for r in band:
        for c in [0, 11, 22]:
            v = grid[r][c]
            if v not in [3, 9]:
                vals_in_band.add(v)
    if not vals_in_band:
        continue
    val_repr = frozenset(vals_in_band)
    if current_val is None or val_repr != current_val:
        blocks.append(val_repr)
        current_val = val_repr
print(f"\nContiguous blocks by marker value per band: {blocks}")
print(f"Number of blocks: {len(blocks)}")

# So we have 2 blocks! Maybe output is a simple indicator of this?

# What if output shows which BLOCK each row/column belongs to?
# With 2 blocks and potentially 3 columns → could be something like 2×3 showing block assignments

block_assignments = {}
for i, band in enumerate(bands):
    vals_in_band = set()
    for r in band:
        for c in [0, 11, 22]:
            v = grid[r][c]
            if v not in [3, 9]:
                vals_in_band.add(v)
    if not vals_in_band:
        continue
    val_repr = tuple(sorted(vals_in_band))
    block_assignments[i] = val_repr
print(f"\nBlock value mapping: {block_assignments}")

# Block 0-2 → (5,) 
# Block 3 → (4,)

# If output has shape 4×3 showing what "type" each region-column combo is:
output_type_grid = []
for i, band in enumerate(bands):
    row = []
    for c_idx, c in enumerate([0, 11, 22]):
        vals = set(grid[r][c] for r in band if grid[r][c] not in [3, 9])
        if vals:
            # Encode as index into sorted unique values
            all_vals = tuple(sorted(vals))
            row.append(list(all_vals)[0] if len(all_vals) == 1 else sum(all_vals))
        else:
            row.append(-1)  # Empty cell
    output_type_grid.append(row)
    print(output_type_grid[-1])

# Count contiguous active segments per column
marker_cols = [0, 11, 22]
segments_per_col = {}

for c in marker_cols:
    segment_start = None
    segment_values = []
    segments = []

    for r in range(len(grid)):
        val = grid[r][c]
        if val not in [3, 9]:
            if segment_start is None:
                segment_start = r
            segment_values.append((r, val))
        else:
            if segment_start is not None:
                segments.append(segment_values)
                segment_start = None
                segment_values = []

    # Don't forget last segment
    if segment_start is not None:
        segments.append(segment_values)

    if segments:
        # Extract first value of each segment
        seg_first_vals = [s[0][1] for s in segments]
        seg_lengths = [len(s) for s in segments]
        segments_per_col[c] = {'segments': segments, 'first_vals': seg_first_vals, 'lengths': seg_lengths}
        print(f"Col {c}: segments = {seg_first_vals}, lengths = {seg_lengths}")

# Max number of segments across columns?
all_seg_counts = [len(segments_per_col[c]['segments']) for c in marker_cols]
print(f"\nMax segments in any column: {max(all_seg_counts)}")

# What if output is 2×3 where each row represents a segment tier?
# Or maybe 3×2 transposed?

import json
result = {"action": "request_demos"}
print(json.dumps(result))

# Correct calculation: count per band×value per column
print("Active columns per band and value:")
for i, band in enumerate(bands):
    print(f"Band {i} ({band[0]}-{band[1]}):")
    for c in [0, 11, 22]:
        val = None
        for r in range(band[0], band[1]+1):
            v = grid[r][c]
            if v not in [3, 9]:
                val = v
                break
        print(f"  Col {c}: {val}")

# Try: count of distinct values per row of input (across marker columns)
print("Distinct values per input row (at marker cols 0,11,22):")
distinct_per_row = []
for r in range(len(grid)):
    vals = set()
    for c in [0, 11, 22]:
        v = grid[r][c]
        if v not in [3, 9]:
            vals.add(v)
    distinct_per_row.append(sorted(list(vals)))

# This gives us a sequence. Which rows have content?
active_rows_with_distinct = [(r, len(set(row[0]))) for r, row in enumerate(distinct_per_row)]
print(f"\nActive rows with distinct count: {[(r,d) for r,d in active_rows_with_distinct if d > 0]}")

# Maybe just show the unique row patterns?
unique_patterns = {}
for r, vals in enumerate(distinct_per_row):
    if vals:
        key = tuple(vals)
        if key not in unique_patterns:
            unique_patterns[key] = []
        unique_patterns[key].append(r)

print("\nUnique patterns:")
for pattern, rows in unique_patterns.items():
    print(f"  {pattern}: rows {rows}")

